	let {items,active=$bindable(''),color,variant='default',placement='bottom',size='default',radius='squircle',tone='default',magnification=1.55,distance=110,magnify=true,bounce=true,tilt=true,goo=true,magnetic=true,tooltips=true,pulse=true,disabled=false,onSelect,onActiveChange}:DockProps=$props();
