			if(tracking&&!reduce){const primary=vertical?pointerCross:pointer,secondary=vertical?pointer:pointerCross;const mainStart=vertical?rect.top:rect.left,mainSize=vertical?rect.height:rect.width,crossStart=vertical?rect.left:rect.top,crossSize=vertical?rect.width:rect.height;const mx=vertical?secondary-crossStart:primary-mainStart,my=vertical?primary-mainStart:secondary-crossStart;barEl.style.setProperty('--mx',`${mx.toFixed(1)}px`);barEl.style.setProperty('--my',`${my.toFixed(1)}px`);barEl.style.setProperty('--gx',`${mx.toFixed(1)}px`);barEl.style.setProperty('--gy',`${my.toFixed(1)}px`);barEl.style.setProperty('--glow','1');barEl.style.setProperty('--sheen-o','1');node.style.setProperty('--aux',`${mx.toFixed(1)}px`);node.style.setProperty('--auy',`${my.toFixed(1)}px`);node.style.setProperty('--au-a','1');
				if(variant==='glass'&&tilt){const nx=Math.max(-1,Math.min(1,mx/crossSize*2-1)),ny=Math.max(-1,Math.min(1,my/mainSize*2-1));barEl.style.setProperty('--ry',`${(nx*4).toFixed(2)}deg`);barEl.style.setProperty('--rx',`${(-ny*4).toFixed(2)}deg`)}
				for(const item of els){const r=item.getBoundingClientRect(),center=vertical?r.top+r.height/2:r.left+r.width/2,d=primary-center,gaussian=Math.exp(-(d*d)/(2*distance*distance));if(variant==='gooey'||variant==='neon')continue;if(variant==='magnet'&&magnetic){const influence=Math.max(0,1-Math.abs(d)/distance)**2,crossCenter=vertical?r.left+r.width/2:r.top+r.height/2,crossDelta=secondary-crossCenter,pull=Math.max(-14,Math.min(14,d*.22))*influence,crossPull=Math.max(-10,Math.min(10,crossDelta*.16))*influence;item.style.setProperty('--tx',`${(vertical?crossPull:pull).toFixed(2)}px`);item.style.setProperty('--ty',`${(vertical?pull:crossPull).toFixed(2)}px`);item.style.setProperty('--rot',`${(Math.sign(d)*-7*influence).toFixed(2)}deg`);item.style.setProperty('--s',`${(1+.24*influence).toFixed(3)}`);item.style.setProperty('--near',influence.toFixed(3))}else if(variant==='bounce'&&bounce){const lift=-18*gaussian;item.style.setProperty('--ty',`${lift.toFixed(2)}px`);item.style.setProperty('--sx',`${(1-.06*gaussian).toFixed(3)}`);item.style.setProperty('--sy',`${(1+.16*gaussian).toFixed(3)}`);item.style.setProperty('--near',gaussian.toFixed(3))}else if(((variant==='default'||variant==='aurora')&&magnify)||(variant==='glass'&&tilt)){const scale=variant==='glass'?1+.12*gaussian:1+(magnification-1)*gaussian,lift=variant==='glass'?-6*gaussian:-.34*r.height*gaussian,side=-Math.sign(d)*.16*r.width*gaussian;item.style.setProperty('--s',scale.toFixed(4));item.style.setProperty('--ty',`${(vertical?side:lift).toFixed(2)}px`);item.style.setProperty('--tx',`${(vertical?lift:side).toFixed(2)}px`);item.style.setProperty('--near',gaussian.toFixed(3))}}
