		barEl.addEventListener('pointermove',move,{passive:true});barEl.addEventListener('pointerleave',leave);barEl.addEventListener('pointerover',over);barEl.addEventListener('focusin',over);barEl.addEventListener('pointerdown',press);barEl.addEventListener('keydown',keydown);const resize=()=>{leave();updateGoo()};window.addEventListener('resize',resize,{passive:true});const observer=new MutationObserver(updateGoo);observer.observe(barEl,{subtree:true,attributes:true,attributeFilter:['data-active']});requestAnimationFrame(()=>{const chosen=barEl.querySelector<HTMLElement>('[data-active="true"]');measureRail(chosen);railX=railTargetX;railW=railTargetW*.6;updateGoo();if(variant==='neon')update(0)});
