</script>

<nav class="rx-dock rx-dock--{variant} rx-dock--{placement} rx-dock--{size} rx-dock--r-{radius} rx-dock--t-{tone}" class:is-pulse={pulse} class:no-goo={!goo} class:is-disabled={disabled} aria-label="Application dock" style={styleColor(color)??`--rx-color:var(--rx-${tone==='default'?'primary':tone})`} {@attach dockPhysics} {@attach attachNeighbor}>
	<div class="rx-dock__stage"><span class="rx-dock__aurora" aria-hidden="true"></span><span class="rx-dock__halo" aria-hidden="true"></span>
		<div class="rx-dock__bar" data-rx-dock-bar role="toolbar" aria-label="Dock controls" aria-disabled={disabled?'true':undefined}><span class="rx-dock__sheen" aria-hidden="true"></span><span class="rx-dock__edge" aria-hidden="true"></span><span class="rx-dock__glow" aria-hidden="true"></span>
